import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { ArrowRight, Play, Activity, Wand2, Loader2, X, Check } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const data = [
  { name: 'Jan', uv: 4000, pv: 2400, amt: 2400 },
  { name: 'Feb', uv: 3000, pv: 1398, amt: 2210 },
  { name: 'Mar', uv: 2000, pv: 9800, amt: 2290 },
  { name: 'Apr', uv: 2780, pv: 3908, amt: 2000 },
  { name: 'May', uv: 1890, pv: 4800, amt: 2181 },
  { name: 'Jun', uv: 2390, pv: 3800, amt: 2500 },
  { name: 'Jul', uv: 3490, pv: 4300, amt: 2100 },
];

const themes = ['Neural Network', 'Data Flow', 'Quantum Mesh', 'Cyber Gradient'];

const Hero: React.FC = () => {
  const [showGenerator, setShowGenerator] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [bgImage, setBgImage] = useState<string | null>(null);
  const [selectedTheme, setSelectedTheme] = useState('Neural Network');

  const handleGenerate = async () => {
    if (!process.env.API_KEY) {
        alert("API Key not found in environment.");
        return;
    }
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Abstract enterprise website background, ${selectedTheme} style, white, light grey and silver color palette with subtle indigo and teal accents, high key, minimalist, geometric, professional, soft lighting, 8k resolution`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [{ text: prompt }]
        },
        config: {
            imageConfig: {
                aspectRatio: "16:9"
            }
        }
      });

      const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (part && part.inlineData) {
        setBgImage(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
      }
    } catch (e) {
      console.error("Failed to generate image", e);
      alert("Failed to generate image. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <section className="relative pt-32 pb-20 lg:pt-48 lg:pb-32 overflow-hidden bg-slate-50 transition-all duration-500">

      {/* Background Rendering */}
      {bgImage ? (
          <div className="absolute inset-0 z-0 animate-in fade-in duration-1000">
             <img src={bgImage} alt="AI Generated Background" className="w-full h-full object-cover opacity-60" />
             <div className="absolute inset-0 bg-gradient-to-b from-slate-50/50 via-transparent to-slate-50/80" />
          </div>
      ) : (
          <>
            <div className="absolute top-0 right-0 -translate-y-1/4 translate-x-1/4 w-[800px] h-[800px] bg-teal-500/10 rounded-full blur-3xl z-0" />
            <div className="absolute bottom-0 left-0 translate-y-1/4 -translate-x-1/4 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-3xl z-0" />
          </>
      )}

      {/* AI Generator Control */}
      <div className="absolute top-24 right-6 z-30 md:top-32 md:right-12">
        <button 
            onClick={() => setShowGenerator(!showGenerator)}
            className="flex items-center justify-center w-12 h-12 bg-white rounded-full shadow-lg border border-indigo-100 text-indigo-600 hover:bg-indigo-50 hover:scale-105 transition-all"
            title="Generate AI Background"
        >
            <Wand2 className="h-5 w-5" />
        </button>

        {showGenerator && (
            <div className="absolute top-14 right-0 w-80 bg-white/80 backdrop-blur-xl border border-white/40 shadow-2xl rounded-2xl p-5 animate-in fade-in zoom-in-95 origin-top-right">
                <div className="flex justify-between items-center mb-4">
                    <div className="flex items-center gap-2">
                        <Wand2 className="h-4 w-4 text-indigo-600" />
                        <h3 className="text-slate-900 font-semibold text-sm">Theme Generator</h3>
                    </div>
                    <button onClick={() => setShowGenerator(false)} className="text-slate-400 hover:text-slate-700 transition-colors">
                        <X className="h-4 w-4"/>
                    </button>
                </div>

