                            <div>
                                <h3 className="text-xl font-bold text-white mb-2 group-hover:text-brand-lime transition-colors">{benefit.title}</h3>
                                <p className="text-slate-400 text-sm leading-relaxed">{benefit.description}</p>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            <div className="mt-12 p-6 bg-gradient-to-r from-brand-violet to-indigo-600 rounded-2xl text-white relative overflow-hidden">
                <div className="relative z-10 flex items-center justify-between">
